    void smallGround(Canvas c,float l,float t,float r,float b,String s){rr(c,l,t,r,b,WHITE,14);rr(c,l+4,t+4,r-4,t+40,MAROON,10);ct(c,"✦",(l+r)/2,t+29,18,GOLD,true);ct(c,s,(l+r)/2,t+58,8,DEEP,true);ct(c,"View details",(l+r)/2,t+73,7,MUTED,false);}
    void grounds(Canvas c,float w,float h){bg(c,w,h);top(c,"Garba Grounds");rr(c,16,65,w-16,108,WHITE,22);tx(c,"⌕  Search grounds in Vadodara...",30,92,12,MUTED,false);String[] f={"All","Popular","Nearby","A to Z"};float x=18;for(String s:f){rr(c,x,122,x+62,154,s.equals("All")?GOLD:WHITE,17);ct(c,s,x+31,143,9,DEEP,true);x+=69;}tx(c,"Vadodara Garba directory",18,184,17,DEEP,true);tx(c,"Add venue information from your community.",18,204,10,MUTED,false);ArrayList<String> list=new ArrayList<>();list.addAll(grounds);if(list.size()==0){empty(c,235,"No custom grounds yet","Tap Add Ground to build your personal directory.");}else{int y=225;for(int i=0;i<list.size();i++){groundRow(c,16,y,w-16,list.get(i),i);y+=92;if(y>h-175)break;}}rr(c,18,h-145,w-18,h-92,PINK,22);ct(c,"＋  Add Ground",w/2,h-111,13,WHITE,true);}
