    void create(Canvas c,float w,float h){bg(c,w,h);top(c,"Create");tx(c,"Share your Navratri moment",18,95,20,DEEP,true);tx(c,"Post photos, videos or a Garba memory.",18,117,11,MUTED,false);rr(c,16,140,w-16,285,WHITE,20);ct(c,photo.length()>0?"✓":"＋",w/2,205,42,PINK,true);ct(c,photo.length()>0?"Photo selected":"Add photo / video",w/2,232,13,PINK,true);rr(c,16,300,w-16,350,PINK,20);ct(c,"Create Post",w/2,331,13,WHITE,true);tx(c,"Recent posts",18,395,16,DEEP,true);int y=420;for(String s:posts){rr(c,18,y,w-18,y+65,WHITE,15);tx(c,"●",32,y+38,18,PINK,true);tx(c,s,60,y+28,12,DEEP,true);tx(c,"Just now  •  Garba community",60,y+47,9,MUTED,false);y+=76;if(y>h-90)break;}}
    void chat(Canvas c,float w,float h){bg(c,w,h);top(c,"Community");String[] defaults={"Vadodara Garba Lovers","United Way Group","King Mode Crew","Queen Mode Circle","Photography Hub"};int y=75;for(String s:defaults){rr(c,16,y,w-16,y+62,WHITE,15);rr(c,26,y+10,70,y+54,MAROON,22);ct(c,"✦",48,y+39,16,GOLD,true);tx(c,s,82,y+27,13,DEEP,true);tx(c,"Community conversation",82,y+45,9,MUTED,false);y+=72;}for(String s:messages){rr(c,16,y,w-16,y+55,0xFFFFE7A8,15);tx(c,"You",30,y+22,10,PINK,true);tx(c,s,30,y+42,11,DEEP,false);y+=64;if(y>h-160)break;}rr(c,16,h-140,w-16,h-88,PINK,20);ct(c,"＋  New conversation",w/2,h-107,13,WHITE,true);}
    void profile(Canvas c,float w,float h){bg(c,w,h);top(c,"My Profile");ct(c,king?"♛":"♕",w/2,105,54,GOLD,true);ct(c,name,w/2,142,20,DEEP,true);ct(c,"Garba  |  Culture  |  Vadodara",w/2,162,10,MUTED,false);rr(c,16,184,w-16,234,WHITE,18);ct(c,name.equals("Guest")?"Login / Create account":"Edit profile",w/2,215,12,PINK,true);String[] rows={"♡  My Bookmarks","▣  My Posts","★  My Events","♧  Invite Friends","⚙  Settings","?  Help & Support"};int y=270;for(String s:rows){tx(c,s,28,y,13,DEEP,true);tx(c,"›",w-35,y,18,MUTED,false);y+=48;}rr(c,16,570,w-16,620,GOLD,20);ct(c,king?"Switch to Queen Mode":"Switch to King Mode",w/2,602,12,DEEP,true);}
    void trending(Canvas c,float w,float h){bg(c,w,h);top(c,"Trending");rr(c,16,65,w-16,108,WHITE,20);ct(c,"🔥  Trending in Vadodara",w/2,92,13,PINK,true);String[] tags={"All","Photos","Videos","Reels"};float x=18;for(String s:tags){rr(c,x,122,x+62,154,s.equals("Photos")?GOLD:WHITE,17);ct(c,s,x+31,143,9,DEEP,true);x+=69;}String[] p={"Garba vibes","Vadodara tonight","King Mode","Queen Mode","Navratri memories"};int y=180;for(String s:p){rr(c,16,y,w-16,y+120,WHITE,18);rr(c,26,y+10,w/2,y+110,DEEP,14);ct(c,"✦",w/4,y+67,30,GOLD,true);tx(c,"#"+s.replace(" ",""),w/2+10,y+42,13,DEEP,true);tx(c,"Community post  •  ♥",w/2+10,y+66,10,MUTED,false);rr(c,w/2+10,y+80,w-28,y+103,0xFFFFE7A8,12);ct(c,"Like  •  Comment  •  Share",3*w/4+2,y+96,8,PINK,true);y+=135;}}
    void days(Canvas c,float w,float h){bg(c,w,h);top(c,"Navratri Days");tx(c,"Explore all 12 days",18,82,20,WHITE,true);tx(c,"Choose a day to view its Garba focus.",18,104,10,0xFFFFE5B4,false);int y=130;for(int i=1;i<=12;i++){float l=18+((i-1)%3)*(w-36)/3,t=y+((i-1)/3)*68,r=l+(w-48)/3;rr(c,l,t,r,t+52,i==day?GOLD:WHITE,15);ct(c,"Day "+i,(l+r)/2,t+22,11,DEEP,true);ct(c,"Navratri",(l+r)/2,t+39,8,MUTED,false);}y=425;rr(c,18,y,w-18,y+205,0xFFFFE9C7,20);ct(c,"NAVRATRI DAY "+day,w/2,y+42,12,PINK,true);ct(c,"Garba • Energy • Community",w/2,y+82,19,DEEP,true);ct(c,"Discover posts, places and people",w/2,y+111,11,MUTED,false);rr(c,40,y+135,w-40,y+180,PINK,20);ct(c,"Explore Day "+day,w/2,y+164,12,WHITE,true);}
