    void detail(Canvas c,float w,float h){bg(c,w,h);top(c,detail>=0&&detail<grounds.size()?grounds.get(detail):"Ground Details");rr(c,16,65,w-16,260,DEEP,20);ct(c,"✦",w/2,145,58,GOLD,true);ct(c,detail>=0&&detail<grounds.size()?grounds.get(detail):"Garba Ground",w/2,198,20,WHITE,true);ct(c,"Vadodara  •  Community directory",w/2,220,10,0xFFFFE5B4,false);rr(c,18,285,w-18,335,WHITE,18);ct(c,"About",w/2,317,12,PINK,true);tx(c,"Information for this venue can be added and verified by the community.",25,375,11,MUTED,false);rr(c,18,420,w-18,470,PINK,20);ct(c,"Add information",w/2,451,13,WHITE,true);}
    void bottom(Canvas c,float w,float h){float top=h-68;rr(c,0,top,w,h,WHITE,0);for(int i=0;i<5;i++){float x=w*(i+.5f)/5;int col=screen==i?PINK:MUTED;ct(c,tabs[i],x,top+27,17,col,true);ct(c,names[i],x,top+48,7,col,screen==i);}}
    @Override public boolean onTouchEvent(MotionEvent e){if(e.getAction()==0){sx=e.getX();sy=e.getY();return true;}if(e.getAction()!=1)return true;float x=e.getX(),y=e.getY(),w=getWidth(),h=getHeight();
      if(screen==7){if(y>110&&y<345){king=false;save();screen=0;}else if(y>345&&y<585){king=true;save();screen=0;}invalidate();return true;}
      if(y>h-82){screen=Math.min(4,(int)(x/(w/5)));detail=-1;invalidate();return true;}
      if(screen==0){if(y>135&&y<290){day++;if(day>12)day=1;save();invalidate();return true;}if(y>470&&y<555){if(x<w/4)screen=1;else if(x<w/2)screen=5;else if(x<3*w/4)screen=6;else screen=3;invalidate();return true;}if(y>705){king=x<w/2;save();invalidate();return true;}if(y>575&&y<700){screen=1;invalidate();return true;}}
      else if(screen==1){if(y>h-170){textDialog("Add Ground","Ground name",false,"ground");return true;}if(y>215&&y<h-170&&grounds.size()>0){int i=(int)((y-225)/92);if(i>=0&&i<grounds.size()){detail=i;screen=8;invalidate();return true;}}}
      else if(screen==2){if(y>135&&y<285){choosePhoto();return true;}if(y>295&&y<360){textDialog("Create Post","Write your Garba moment",true,"post");return true;}}
      else if(screen==3){if(y>h-160){textDialog("New conversation","Write a message",false,"chat");return true;}}
      else if(screen==4){if(y>175&&y<245){if(name.equals("Guest"))login();else textDialog("Edit profile","Your name",false,"name");return true;}if(y>555&&y<640){king=!king;save();invalidate();return true;}}
      else if(screen==5){if(y>120&&y<170){invalidate();return true;}}
      else if(screen==6){if(y>=125&&y<410){int col=(int)((x-18)/((w-36)/3));int row=(int)((y-130)/68);if(col>=0&&col<3&&row>=0&&row<4){day=row*3+col+1;if(day>12)day=12;save();invalidate();return true;}}}
      else if(screen==8){if(y>400&&y<490){textDialog("Add information","Verified details",true,"ground");return true;}}
      return true;}
